function handler(input) {
  const url = String(input.base_url || '').trim();
  const tokenMatch = url.match(/\/base\/([A-Za-z0-9]+)/);
  const tableMatch = url.match(/[?&]table=([^&#]+)/);
  if (!tokenMatch) throw new Error('请在“设置多维表格信息”节点填写多维表格 URL');
  return { app_token: tokenMatch[1], main_table_id: tableMatch ? decodeURIComponent(tableMatch[1]) : '' };
}

function handler(input) {
  const form = Array.isArray(input.form) ? input.form : [];
  const tables = Array.isArray(input.tables) ? input.tables : [];
  const tableId = name => (tables.find(t => t.name === name) || {}).table_id || '';
  const valueOf = item => {
    if (!item) return '';
    const v = item.value;
    if (Array.isArray(v)) return v.map(x => x && typeof x === 'object' ? (x.text ?? x.name ?? x.value ?? x.id ?? '') : x).join('');
    if (v && typeof v === 'object') return v.text ?? v.name ?? v.value ?? v.id ?? '';
    return v ?? '';
  };
  const scalar = {};
  let detailRows = [];
  for (const item of form) {
    if (item.type === 'fieldList') {
      detailRows = (item.value || []).map(row => {
        const fields = {};
        for (const child of row || []) fields[child.name] = valueOf(child);
        return {
          line_no: String(fields['明细编号'] || '').trim(),
          material_category: String(fields['品类名称'] || '').trim(),
          product_model: String(fields['产品型号名称'] || '').trim(),
          language: String(fields['语种名称'] || '').trim(),
          issue_quantity: Number(fields['实际发放数量'] ?? fields['审批通过数量'] ?? fields['申请数量'])
        };
      });
    } else {
      scalar[item.name] = valueOf(item);
    }
  }
  const requestNo = String(scalar['申请单号'] || scalar['物料申请单号'] || scalar['申请编号'] || '').trim();
  const instanceCode = String(input.instance_code || '').trim();
  if (!requestNo) throw new Error('审批表单中未找到“申请单号”');
  if (!detailRows.length) throw new Error('审批表单中未找到明细控件');
  const lineCounts = detailRows.reduce((counts, row) => {
    counts[row.line_no] = (counts[row.line_no] || 0) + 1;
    return counts;
  }, {});
  detailRows = detailRows.map((d, i) => {
    if (!d.line_no) throw new Error(`第 ${i + 1} 条审批明细缺少“明细编号”`);
    if (!d.line_no.startsWith(`${requestNo}-`)) throw new Error(`第 ${i + 1} 条明细编号 ${d.line_no} 与申请单号不一致`);
    if (!Number.isFinite(d.issue_quantity) || d.issue_quantity < 0) throw new Error(`第 ${i + 1} 条实际发放数量不能小于 0`);
    const signature = [d.material_category, d.product_model, d.language].join('|');
    const idempotencyKey = lineCounts[d.line_no] > 1
      ? `issue:${instanceCode}:${d.line_no}:${signature}`
      : `issue:${instanceCode}:${d.line_no}`;
    return {
      ...d,
      request_no: requestNo,
      instance_code: instanceCode,
      idempotency_key: idempotencyKey,
      ledger_filter: makeFilter('幂等键', idempotencyKey),
      detail_filter: makeFilter('明细编号', d.line_no)
    };
  });
  const ids = {
    main: input.main_table_id || tableId('物料申请单'),
    detail: tableId('申请明细'),
    material: tableId('物料主数据'),
    ledger: tableId('库存流水'),
    queue: tableId('后台任务队列')
  };
  for (const [name, id] of Object.entries(ids)) if (!id) throw new Error(`未找到数据表：${name}`);
  return {
    ...ids,
    request_no: requestNo,
    request_filter: makeFilter('申请单号', requestNo),
    details: detailRows,
    approved_at: Number(input.end_time || Date.now()),
    notify_task_id: `writeback-notify:${instanceCode}`,
    notify_filter: makeFilter('幂等键', `writeback-notify:${instanceCode}`)
  };
}
function makeFilter(fieldName, value) {
  return {
    conjunction: 'and',
    conditions: [{ field_name: fieldName, operator: 'is', value: [String(value)] }]
  };
}

function handler(input) {
  const payload =
    input && input.data
      ? input.data
      : {};

  const items =
    payload.data &&
    Array.isArray(
      payload.data.items
    )
      ? payload.data.items
      : Array.isArray(
          payload.items
        )
      ? payload.items
      : [];

  return {
    should_process:
      items.length === 0,
  };
}

function handler(input) {
  const items = input.detail && input.detail.data && Array.isArray(input.detail.data.items)
    ? input.detail.data.items
    : [];
  const expected = input.expected || {};
  const normalized = value => String(value == null ? '' : value).replace(/\s+/g, '').toLowerCase();
  const fieldText = (fields, name) => {
    const value = fields && fields[name];
    if (Array.isArray(value)) return value.map(item => {
      if (item && typeof item === 'object') return item.text ?? item.name ?? item.value ?? '';
      return item ?? '';
    }).filter(Boolean).join('');
    if (value && typeof value === 'object') return value.text ?? value.name ?? value.value ?? '';
    return value == null ? '' : String(value);
  };
  const matches = items.filter(detail => {
    const fields = detail.fields || {};
    return normalized(fieldText(fields, '物料品类')) === normalized(expected.material_category)
      && normalized(fieldText(fields, '产品型号')) === normalized(expected.product_model)
      && normalized(fieldText(fields, '语种')) === normalized(expected.language);
  });
  const candidates = items.length === 1 ? items : matches;
  if (candidates.length !== 1) {
    throw new Error(`明细编号 ${input.line_no} 结合品类/型号/语种后应唯一命中 1 条，实际 ${candidates.length} 条`);
  }
  const detail = candidates[0];
  const linked = detail.fields && detail.fields['物料编码'];
  let materialRecordId = '';
  if (linked && Array.isArray(linked.link_record_ids)) materialRecordId = linked.link_record_ids[0] || '';
  else if (Array.isArray(linked)) {
    const first = linked[0];
    materialRecordId = typeof first === 'string' ? first : (first && (first.record_id || first.link_record_id || first.id || (first.record_ids || [])[0])) || '';
  } else if (typeof linked === 'string') materialRecordId = linked;
  if (!materialRecordId) throw new Error(`明细编号 ${input.line_no} 未关联物料编码记录`);
  return {
    detail_record_id: detail.record_id,
    material_record_id: materialRecordId,
    material_record_ids: [materialRecordId]
  };
}

function handler(input) {
  const data = input.material && input.material.data || {};
  const materialItems = Array.isArray(data.records) ? data.records : (Array.isArray(data.items) ? data.items : []);
  if (materialItems.length !== 1) throw new Error(`明细编号 ${input.line.line_no} 的物料应命中 1 条，实际 ${materialItems.length} 条`);
  const materialFields = materialItems[0].fields || {};
  const before = Number(materialFields['当前库存']);
  const issue = Number(input.line.issue_quantity);
  if (!Number.isFinite(before)) throw new Error('当前库存不是有效数字');
  if (!Number.isFinite(issue) || issue < 0) throw new Error('实际发放数量不能小于 0');
  const after = before - issue;
  return {
    valid: true,
    material_record_id: materialItems[0].record_id,
    detail_record_id: input.detail_reference.detail_record_id,
    material_category: fieldText(materialFields, '物料品类'),
    product_model: fieldText(materialFields, '产品型号'),
    language: fieldText(materialFields, '语种'),
    before_quantity: before,
    issue_quantity: issue,
    after_quantity: after,
    quantity_delta: -issue,
    now: Date.now()
  };
}
function fieldText(fields, name) {
  const value = fields && fields[name];
  if (Array.isArray(value)) {
    return value.map(item => {
      if (item && typeof item === 'object') return item.text ?? item.name ?? item.value ?? '';
      return item ?? '';
    }).filter(Boolean).join('');
  }
  if (value && typeof value === 'object') return value.text ?? value.name ?? value.value ?? '';
  return value == null ? '' : String(value);
}

function handler(input) {
  return {
    '审批通过数量': input.issue_quantity,
    '实际发放数量': input.issue_quantity,
    '明细状态': '已发放',
    '发放时间': String(input.now),
    '库存流水': [input.ledger_record_id],
    '出库流水编号': input.idempotency_key
  };
}

function handler(input) {
